EDITS = {'apps/desktop/e2e/history-navigation.spec.ts': {'sha256': 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'edits': [[0, 0, '/** Real SQLite -> serve -> Electron history navigation; the mock only replaces inference. */\nimport { execFileSync } from \'node:child_process\'\nimport * as path from \'node:path\'\n\nimport { writeEnvFile, writeMockProviderConfig } from \'../../../tests-js/scripts/mock-provider-config\'\nimport { startMockServer } from \'../../../tests-js/scripts/mock-server\'\n\nimport { buildAppEnv, createSandbox, launchDesktop, waitForAppReady } from \'./fixtures\'\nimport { expect, test } from \'./test\'\n\nconst title = \'E2E bounded history navigation\'\n\ntest(\'exact rail targets, sequential newer pages and explicit live-tail return\', async ({}, testInfo) => {\n  test.setTimeout(180_000)\n  const python = process.env.HERMES_DESKTOP_PYTHON\n  if (!python) throw new Error(\'Set HERMES_DESKTOP_PYTHON to an isolated dependency-complete test interpreter\')\n  const sandbox = createSandbox(\'history-navigation\')\n  const mock = await startMockServer()\n  writeMockProviderConfig(sandbox.hermesHome, mock.url)\n  writeEnvFile(sandbox.hermesHome, \'e2e-mock-key\', mock.url)\n  let app: Awaited<ReturnType<typeof launchDesktop>>[\'app\'] | undefined\n  try {\n    const root = path.resolve(import.meta.dirname, \'../../..\')\n    execFileSync(python, [\'-c\', `\nfrom pathlib import Path\nfrom hermes_state import SessionDB\nimport sys\nwith SessionDB(db_path=Path(sys.argv[1]) / \'state.db\') as db:\n    sid = \'e2e-history-navigation\'\n    db.create_session(session_id=sid, source=\'desktop\')\n    db.set_session_title(sid, sys.argv[2])\n    rows = []\n    for turn in range(40):\n        rows.append({\'role\': \'user\', \'content\': f\'NAV prompt {turn:02}\', \'timestamp\': turn + 1})\n        rows.append({\'role\': \'assistant\', \'content\': (\'### Navigation answer\\n\\n\' + \'A durable paragraph for measuring the selected turn. \' * 30), \'timestamp\': turn + 1})\n        if turn == 20:\n            for tool in range(250):\n                rows.append({\'role\': \'assistant\', \'content\': f\'Navigation tool step {tool}\', \'timestamp\': 21,\n                    \'tool_calls\': [{\'id\': f\'nav-{tool}\', \'type\': \'function\', \'function\': {\'name\': \'terminal\', \'arguments\': \'{}\'}}]})\n                rows.append({\'role\': \'tool\', \'tool_name\': \'terminal\', \'tool_call_id\': f\'nav-{tool}\', \'content\': f\'Navigation result {tool}\', \'timestamp\': 21})\n    db.append_messages_batch(sid, rows)\n    db.end_session(sid)\n`, sandbox.hermesHome, title], { cwd: root, env: buildAppEnv(sandbox) })\n    const launched = await launchDesktop(buildAppEnv(sandbox))\n    app = launched.app\n    const page = launched.page\n    await waitForAppReady({ app, page, mock, mockUrl: mock.url, sandbox, cleanup: async () => {} }, 120_000)\n    await page.locator(\'[data-slot="sidebar"] button\').filter({ hasText: title }).first().click()\n    const viewport = page.locator(\'[data-slot="aui_thread-viewport"]\').first()\n    await expect(viewport).toContainText(\'NAV prompt 39\')\n    const rail = page.locator(\'[data-slot="thread-timeline-ticks"]\').first()\n    await expect(rail).toBeVisible()\n    await rail.evaluate(element => { element.scrollTop = 0 })\n    await rail.getByRole(\'button\', { name: \'NAV prompt 00\', exact: true }).click()\n    const target = viewport.locator(\'[data-message-id="history-row-1"]\')\n    await expect(target).toBeVisible()\n    await expect.poll(() => target.evaluate(element => {\n      const viewport = element.closest(\'[data-slot="aui_thread-viewport"]\')!\n      const group = element.closest(\'[data-slot="aui_message-group"]\')!\n      return Math.abs(group.getBoundingClientRect().top - viewport.getBoundingClientRect().top - 8)\n    })).toBeLessThanOrEqual(2)\n    await expect(rail.getByRole(\'button\', { name: \'NAV prompt 00\', exact: true })).toHaveAttribute(\'aria-current\', \'location\')\n    await page.screenshot({ path: testInfo.outputPath(\'exact-history-target.png\') })\n    const later = viewport.getByRole(\'button\', { name: \'Show later messages\' })\n    for (let pageNumber = 0; pageNumber < 4; pageNumber += 1) {\n      const before = await viewport.textContent()\n      await later.click()\n      await expect.poll(() => viewport.textContent()).not.toBe(before)\n      expect(await viewport.locator(\'[data-message-id]\').count()).toBeLessThanOrEqual(360)\n    }\n    await expect(viewport).toContainText(\'NAV prompt 39\')\n    await expect(later).toHaveCount(0)\n    await expect(viewport.getByRole(\'button\', { name: \'Show earlier messages\' })).toBeVisible()\n    await page.getByRole(\'button\', { name: \'Jump to latest\', exact: true }).click()\n    await expect(viewport.locator(\'[data-message-id^="history-"]\')).toHaveCount(0)\n    await expect(viewport).toContainText(\'NAV prompt 39\')\n    await page.screenshot({ path: testInfo.outputPath(\'returned-live-tail.png\') })\n  } finally {\n    await app?.close().catch(() => undefined)\n    await mock.close()\n    sandbox.cleanup()\n  }\n})\n']]}, 'apps/desktop/src/app/chat/history-window.test.tsx': {'sha256': '6594bc479ff3c4e6198d68b6113a4d58da205ebf6b63debcabb25b9297bd77f3', 'edits': [[8, 8, "import type { SessionMessage } from '@/types/hermes'\n"], [25, 26, "  pagination: { has_older: true, has_newer: true, limit: 120, offset: 40, returned: 120, order: 'oldest', first_cursor: rowId, last_cursor: rowId + 119 },\n"], [270, 275, ''], [276, 284, "describe('adjacent history windows', () => {\n  it('walks a tool turn longer than 120 rows in both directions, retains a bounded window and rejoins split calls', async () => {\n    const rows: SessionMessage[] = [{ id: 1, role: 'user', content: 'one long turn', timestamp: 1 }]\n    for (let i = 0; i < 300; i += 1) {\n      rows.push({ id: 2 + i * 2, role: 'assistant', content: '', timestamp: 1,\n        tool_calls: [{ id: `call-${i}`, type: 'function', function: { name: 'terminal', arguments: '{}' } }] },\n        { id: 3 + i * 2, role: 'tool', tool_call_id: `call-${i}`, tool_name: 'terminal', content: `result-${i}`, timestamp: 1 })\n    }\n    rows.push({ id: 602, role: 'user', content: 'next turn', timestamp: 1 })\n    const api = vi.spyOn(window.hermesDesktop, 'api').mockImplementation(async request => {\n      const params = new URL(request.path, 'http://test').searchParams\n      const start = params.has('before_cursor') ? Math.max(0, Number(params.get('before_cursor')) - 121)\n        : params.has('after_cursor') ? Number(params.get('after_cursor')) : Number(params.get('row_id')) - 1\n      const selected = rows.slice(start, start + 120)\n      return { session_id: 'stored', messages: selected, pagination: {\n        limit: 120, returned: selected.length, offset: start, order: 'oldest',\n        has_older: start > 0, has_newer: start + selected.length < rows.length,\n        first_cursor: selected[0]?.id, last_cursor: selected.at(-1)?.id,\n        leading_prompt_row_id: start > 0 ? 1 : null\n      } }\n    })\n"], [286, 306, "    await act(async () => { await mounted.window.revealRow(1, new AbortController().signal) })\n    const promptId = mounted.window.currentMessages[0].id\n    const results = new Set<string>()\n    for (let i = 0; i < 5; i += 1) {\n      await act(async () => { expect(await mounted.window.revealNewer()).toBe(true) })\n      const calls = mounted.window.currentMessages.flatMap(message => message.parts).filter(part => part.type === 'tool-call')\n      // Raw retention is three pages even though hundreds of rows hydrate into\n      // one bubble; no cumulative full-transcript hydration.\n      expect(calls.length).toBeLessThanOrEqual(181)\n      for (const part of calls) if (part.result !== undefined) results.add(part.toolCallId)\n      if (i === 0) {\n        const seam = calls.find(part => part.toolCallId === 'call-59')!\n        expect(seam.result).toBeDefined()\n        expect(calls.filter(part => part.toolCallId === 'call-59')).toHaveLength(1)\n        expect(mounted.window.currentMessages[0].id).toBe(promptId)\n      }\n    }\n    expect(results.size).toBe(300)\n    expect(mounted.window.newerAvailable).toBe(false)\n    expect(mounted.window.leadingRowId).toBe(1)\n    expect(mounted.window.currentMessages.at(-1)?.rowId).toBe(602)\n    for (let i = 0; i < 3; i += 1) {\n      await act(async () => { expect(await mounted.window.expandWindow()).toBe(true) })\n    }\n    expect(mounted.window.currentMessages[0].id).toBe(promptId)\n"], [307, 308, '    expect(mounted.window.newerAvailable).toBe(true)\n'], [309, 314, "    expect(api.mock.calls.every(([request]) => request.path.includes('/messages/around?'))).toBe(true)\n    act(() => mounted.window.returnToLatest())\n    expect(mounted.runtime.thread.getState().messages.at(-1)?.id).toBe('live-10119')\n"], [316, 339, "  it.each(['older', 'newer'] as const)('captures %s changes only on commit and ignores a response superseded by a rail jump', async direction => {\n    const api = vi.spyOn(window.hermesDesktop, 'api').mockResolvedValueOnce(page(4000))\n    const mounted = mount()\n    await act(async () => { await mounted.window.revealRow(4000, new AbortController().signal) })\n    let finish!: (value: ReturnType<typeof page>) => void\n    api.mockImplementationOnce(() => new Promise(resolve => { finish = resolve }))\n    const before = vi.fn()\n    let pending!: Promise<boolean | void>\n    act(() => { pending = direction === 'older' ? mounted.window.expandWindow(before) : mounted.window.revealNewer(before) })\n    expect(before).not.toHaveBeenCalled()\n    api.mockResolvedValueOnce(page(8000))\n    await act(async () => { await mounted.window.revealRow(8000, new AbortController().signal) })\n    expect(await pending).toBe(false)\n    await act(async () => { finish(page(direction === 'older' ? 3880 : 4120)); await Promise.resolve() })\n    expect(before).not.toHaveBeenCalled()\n    expect(mounted.window.currentMessages[0].rowId).toBe(8000)\n"], [341, 365, "  it('preserves the selected content on empty, invalid or failed continuations and reports older backend capability', async () => {\n    const api = vi.spyOn(window.hermesDesktop, 'api').mockResolvedValue(page(40))\n    const mounted = mount()\n    await act(async () => { await mounted.window.revealRow(40, new AbortController().signal) })\n    const selected = mounted.window.currentMessages\n    const before = vi.fn()\n    await act(async () => { expect(await mounted.window.revealNewer(before)).toBe(false) })\n    expect(mounted.window.historyError).toBe('failed')\n    expect(mounted.window.currentMessages).toBe(selected)\n    api.mockResolvedValueOnce({ ...page(160), messages: [], pagination: { ...page(160).pagination, returned: 0, has_newer: false } })\n    await act(async () => { expect(await mounted.window.revealNewer(before)).toBe(false) })\n    expect(mounted.window.currentMessages).toBe(selected)\n    expect(mounted.window.newerAvailable).toBe(false)\n    expect(before).not.toHaveBeenCalled()\n    api.mockResolvedValueOnce({ ...page(400), pagination: { ...page(400).pagination, first_cursor: undefined, last_cursor: undefined } })\n    await act(async () => { await mounted.window.revealRow(400, new AbortController().signal) })\n    await act(async () => { expect(await mounted.window.revealNewer()).toBe(false) })\n    expect(mounted.window.historyError).toBe('unavailable')\n    expect(mounted.window.currentMessages[0].rowId).toBe(400)\n"]]}, 'apps/desktop/src/components/assistant-ui/thread/history-scroll.test.ts': {'sha256': 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'edits': [[0, 0, 'import { afterEach, describe, expect, it, vi } from \'vitest\'\n\nimport { captureHistoryScroll, restoreHistoryScroll } from \'./history-scroll\'\nimport { scrollTimelineTarget } from \'./timeline-scroll\'\n\nconst rect = (top: number, height: number) => ({ top, bottom: top + height, height, left: 0, right: 800, width: 800, x: 0, y: top, toJSON: () => ({}) })\n\nafterEach(() => { document.body.innerHTML = \'\'; vi.unstubAllGlobals(); vi.restoreAllMocks() })\n\ndescribe(\'bounded history geometry\', () => {\n  it.each([800, -800])(\'keeps an exact visible occurrence after a %+i pixel append/eviction shift\', shift => {\n    const viewport = document.createElement(\'div\')\n    viewport.innerHTML = \'<div data-slot="aui_message-group" data-history-anchor="old-group"><div data-history-anchor="text-99"></div><div data-history-anchor="text-99"></div></div>\'\n    document.body.append(viewport)\n    viewport.scrollTop = 900\n    vi.spyOn(viewport, \'getBoundingClientRect\').mockImplementation(() => rect(0, 600))\n    const group = viewport.firstElementChild as HTMLElement\n    let displacement = 0\n    vi.spyOn(group, \'getBoundingClientRect\').mockImplementation(() => rect(100 + displacement - viewport.scrollTop, 2000))\n    const children = Array.from(group.children) as HTMLElement[]\n    vi.spyOn(children[0], \'getBoundingClientRect\').mockImplementation(() => rect(200 + displacement - viewport.scrollTop, 100))\n    vi.spyOn(children[1], \'getBoundingClientRect\').mockImplementation(() => rect(1000 + displacement - viewport.scrollTop, 200))\n    const anchors = captureHistoryScroll(viewport)\n    expect(anchors[0]).toEqual({ key: \'text-99\', occurrence: 1, offset: 100 })\n    group.dataset.historyAnchor = \'new-group\' // the old folded assistant head was evicted\n    displacement = shift\n    expect(restoreHistoryScroll(viewport, anchors)).toBe(true)\n    expect(children[1].getBoundingClientRect().top).toBe(100)\n    expect(viewport.scrollTop).toBe(900 + shift)\n  })\n\n  it(\'does not measure descendants of offscreen content-visibility groups\', () => {\n    const viewport = document.createElement(\'div\')\n    viewport.innerHTML = \'<div data-slot="aui_message-group"><div data-history-anchor="hidden"></div></div>\'\n    vi.spyOn(viewport, \'getBoundingClientRect\').mockReturnValue(rect(0, 600))\n    vi.spyOn(viewport.firstElementChild!, \'getBoundingClientRect\').mockReturnValue(rect(-2000, 500))\n    const measure = vi.spyOn(viewport.firstElementChild!.firstElementChild!, \'getBoundingClientRect\')\n    expect(captureHistoryScroll(viewport)).toEqual([])\n    expect(measure).not.toHaveBeenCalled()\n  })\n\n  it.each([false, true])(\'retargets the selected prompt as deferred layout changes (cancel=%s)\', async cancel => {\n    const frames = new Map<number, FrameRequestCallback>()\n    let serial = 0\n    vi.stubGlobal(\'requestAnimationFrame\', (callback: FrameRequestCallback) => { frames.set(++serial, callback); return serial })\n    vi.stubGlobal(\'cancelAnimationFrame\', (id: number) => frames.delete(id))\n    vi.spyOn(performance, \'now\').mockReturnValue(0)\n    const tick = (time: number) => { const callbacks = [...frames.values()]; frames.clear(); for (const callback of callbacks) callback(time) }\n    const viewport = document.createElement(\'div\')\n    viewport.innerHTML = \'<div data-slot="aui_message-group"><div data-slot="aui_turn-pair"><div data-message-id="exact-row"></div></div></div>\'\n    document.body.append(viewport)\n    Object.defineProperty(viewport, \'scrollHeight\', { value: 6000 })\n    Object.defineProperty(viewport, \'clientHeight\', { value: 600 })\n    vi.spyOn(viewport, \'getBoundingClientRect\').mockReturnValue(rect(0, 600))\n    const group = viewport.firstElementChild as HTMLElement\n    group.style.contentVisibility = \'auto\'\n    let layoutTop = 1800\n    vi.spyOn(group, \'getBoundingClientRect\').mockImplementation(() => rect(layoutTop - viewport.scrollTop, 900))\n    const controller = new AbortController()\n    const pending = scrollTimelineTarget(viewport, \'exact-row\', controller.signal)\n    tick(100)\n    layoutTop = 2600 // earlier skipped turns acquired their real height\n    if (cancel) controller.abort()\n    const stoppedAt = viewport.scrollTop\n    tick(200); tick(220); tick(240)\n    expect(await pending).toBe(!cancel)\n    expect(viewport.scrollTop).toBe(cancel ? stoppedAt : 2592)\n    expect(group.style.contentVisibility).toBe(\'auto\')\n    expect(frames.size).toBe(0)\n  })\n})\n']]}, 'apps/desktop/src/components/assistant-ui/thread/list-session-scroll.test.tsx': {'sha256': '3448e8fd8335eef282adfeb0cc0de8907496a72d76e532c3777589e54ed81d7b', 'edits': [[1, 2, "import { act, fireEvent, render, waitFor } from '@testing-library/react'\n"], [962, 962, '\n\ndescribe(\'historical page controls\', () => {\n  it(\'loads newer history on downward intent without jumping live or treating programmatic scroll as paging\', async () => {\n    let finish!: (value: boolean) => void\n    const revealNewer = vi.fn(() => new Promise<boolean>(resolve => { finish = resolve }))\n    const expandWindow = vi.fn(async () => false)\n    const returnToLatest = vi.fn()\n    const { container, getByRole } = render(<ScrollHarness messages={sessionMessages(\'history\', 3)} sessionKey="history"\n      window={{ isHistorical: true, newerAvailable: true, olderAvailable: true, revealNewer, expandWindow, returnToLatest }} />)\n    await settleScroll()\n    const viewport = viewportEl(container)\n    act(() => { viewport.scrollTop = 0; fireEvent.scroll(viewport) })\n    expect(expandWindow).not.toHaveBeenCalled()\n    act(() => { viewport.scrollTop = SCROLL_H - CLIENT_H; fireEvent.scroll(viewport) })\n    expect(revealNewer).not.toHaveBeenCalled()\n    fireEvent.wheel(viewport, { deltaY: 120 })\n    expect(revealNewer).toHaveBeenCalledTimes(1)\n    fireEvent.wheel(viewport, { deltaY: 120 })\n    expect(revealNewer).toHaveBeenCalledTimes(1)\n    expect(getByRole(\'button\', { name: \'Show later messages\' })).toBeDisabled()\n    await act(async () => { finish(false) })\n    fireEvent.click(getByRole(\'button\', { name: \'Show later messages\' }))\n    expect(revealNewer).toHaveBeenCalledTimes(2)\n    await act(async () => { finish(false) })\n    act(() => requestThreadPageScroll(1, \'history\'))\n    expect(revealNewer).toHaveBeenCalledTimes(3)\n    await act(async () => { finish(false) })\n    expect(returnToLatest).not.toHaveBeenCalled()\n  })\n})\n']]}}
